class Solution:
    def maxChunksToSorted(self, arr):
        n = len(arr)
        leftMax = [0] * n
        rightMin = [0] * n
        leftMax[0] = arr[0]
        for i in range(1, n):
            leftMax[i] = max(leftMax[i - 1], arr[i])
        rightMin[n - 1] = arr[n - 1]
        for i in range(n - 2, -1, -1):
            rightMin[i] = min(rightMin[i + 1], arr[i])
        ans = 1
        for i in range(n - 1):
            if leftMax[i] <= rightMin[i + 1]:
                ans += 1
        return ans

