class Solution:
    def maxChunksToSorted(self, arr):
        stack = []
        for x in arr:
            m = x
            while stack and stack[-1] > x:
                m = max(m, stack.pop())
            if stack or m != x:
                stack.append(m)
            else:
                stack.append(x)
        return len(stack)

