class Solution {
public:
    int maxChunksToSorted(vector<int>& arr) {
        vector<int> st;
        for (int x : arr) {
            int m = x;
            while (!st.empty() && st.back() > x) m = max(m, st.back()), st.pop_back();
            st.push_back(m);
        }
        return st.size();
    }
};

