class Solution {
    public int maxChunksToSorted(int[] arr) {
        Deque<Integer> st = new ArrayDeque<>();
        for (int x : arr) {
            int m = x;
            while (!st.isEmpty() && st.peek() > x) m = Math.max(m, st.pop());
            st.push(m);
        }
        return st.size();
    }
}

